window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-38e714e67caca8d6"]={"versions": [{"id": "FIG-38e714e67caca8d6", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Manifests (<code>AUTOSAR_TPS_ManifestSpecification</code>). Das Diagramm modelliert die Zuordnung von Diagnose-Upload- und Download-Funktionalitäten über <code>DiagnosticUploadDownloadPortMapping</code> zu Software-Komponenten, Diagnose-Service-Instanzen und Prozessen auf der AUTOSAR Adaptive Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>DiagnosticCommonElement</code> (Spezialisierung von <code>ARElement</code>): Basisklasse im Diagnose-Metamodell.</li>\n<li><code>DiagnosticServiceInstance</code> (spezialisiert <code>DiagnosticCommonElement</code>): Repräsentiert die Instanz eines Diagnose-Dienstes.</li>\n<li><code>DiagnosticMapping</code> (spezialisiert <code>DiagnosticCommonElement</code>): Abstrakte Basisklasse für Diagnose-Zuordnungen.</li>\n<li><code>DiagnosticSwMapping</code> (spezialisiert <code>DiagnosticMapping</code>): Spezifische Basis für Software-bezogene Diagnose-Mappings.</li>\n<li><code>DiagnosticUploadDownloadPortMapping</code> (spezialisiert <code>DiagnosticSwMapping</code>): Zentrales Mapping-Element für Upload-/Download-Ports.</li>\n<li>Assoziation <code>+serviceInstance</code> (Kardinalität <code>0..1</code>) zu <code>DiagnosticServiceInstance</code>.</li>\n<li>Assoziation <code>+process</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«atpSplitable»</code>) zu <code>ProcessDesign</code>.</li>\n<li>Assoziation <code>+swcServiceDependencyInExecutable</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«instanceRef»</code>) zu <code>SwcServiceDependency</code>.</li>\n<li><code>ProcessDesign</code> (Spezialisierung von <code>ARElement</code>): Modelliert den Entwurf eines Prozesses; verknüpft über die Assoziation <code>+design</code> (Kardinalität <code>0..1</code>) mit <code>Process</code>.</li>\n<li><code>Process</code> (spezialisiert <code>AbstractExecutionContext</code>): Ausführungskontext mit den Attributen:</li>\n<li><code>logTraceDefaultLogLevel: LogTraceDefaultLogLevelEnum [0..1]</code></li>\n<li><code>logTraceFilePath: UriString [0..1]</code></li>\n<li><code>logTraceLogMode: LogTraceLogModeEnum [0..1]</code></li>\n<li><code>logTraceProcessDesc: String [0..1]</code></li>\n<li><code>logTraceProcessId: String [0..1]</code></li>\n<li><code>preMapping: Boolean [0..1]</code></li>\n<li><code>SwcServiceDependency</code> (spezialisiert <code>ServiceDependency</code>, <code>Identifiable</code>, <code>AtpStructureElement</code>): Beschreibt Service-Abhängigkeiten einer Software-Komponente; besitzt eine Komposition <code>+serviceNeeds</code> (Kardinalität <code>1</code>) zu <code>ServiceNeeds</code>.</li>\n<li><code>ServiceNeeds</code> (spezialisiert <code>Identifiable</code>): Abstrakter Dienstbedarf.</li>\n<li><code>DiagnosticCapabilityElement</code> (spezialisiert <code>ServiceNeeds</code>): Spezifiziert Diagnosefähigkeiten mit Attributen:</li>\n<li><code>audience: DiagnosticAudienceEnum [0..*]</code></li>\n<li><code>diagRequirement: DiagRequirementIdString [0..1]</code></li>\n<li><code>securityAccessLevel: PositiveInteger [0..1]</code></li>\n<li><code>DiagnosticUploadDownloadNeeds</code> (spezialisiert <code>DiagnosticCapabilityElement</code>): Konkreter Service-Bedarf für Diagnose-Upload- und Download-Vorgänge.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Strukturdiagramm bildet dieses Diagramm keine direkten Laufzeit- oder Sequenzabläufe ab. Es spezifiziert die deklarativen Zusammenhänge der Manifest-Modellierung zur Entwurfs- und Konfigurationszeit: Eine Software-Komponente deklariert über <code>SwcServiceDependency</code> ihren Bedarf an Diagnose-Upload/-Download-Funktionen (<code>DiagnosticUploadDownloadNeeds</code>). <code>DiagnosticUploadDownloadPortMapping</code> verknüpft diese Service-Abhängigkeit instanzreferenzierend (<code>«instanceRef»</code>) mit der konkreten <code>DiagnosticServiceInstance</code> sowie mit dem zugehörigen Ausführungsprozess (<code>ProcessDesign</code> bzw. <code>Process</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modell definiert verbindliche Vorgaben für die Manifest-Konfiguration der AUTOSAR Adaptive Platform. Attribute wie <code>preMapping</code> und Logging-Konfigurationen (<code>logTrace...</code>) steuern die Initialisierung und Ablaufüberwachung des Prozesses durch das adaptive Ausführungsmanagement (Execution Management). Die Instanzreferenz <code>swcServiceDependencyInExecutable</code> stellt die formale Brücke zwischen komponentenseitigem Service-Bedarf und der Bereitstellung auf Plattformebene dar; die Splitbarkeit (<code>«atpSplitable»</code>) der Assoziation zum Prozess erlaubt die Verteilung der Manifest-Artefakte über getrennte Modelldateien (z. B. Trennung von Applikations- und Maschinenkonfiguration).</p>"}, {"id": "FIG-e24062be900c61bc", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Manifests (<code>AUTOSAR_TPS_ManifestSpecification</code>). Das Diagramm modelliert die Zuordnung von Diagnose-Upload- und Download-Funktionalitäten über <code>DiagnosticUploadDownloadPortMapping</code> zu Software-Komponenten, Diagnose-Service-Instanzen und Prozessen auf der AUTOSAR Adaptive Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>DiagnosticCommonElement</code> (Spezialisierung von <code>ARElement</code>): Basisklasse im Diagnose-Metamodell.</li>\n<li><code>DiagnosticServiceInstance</code> (spezialisiert <code>DiagnosticCommonElement</code>): Repräsentiert die Instanz eines Diagnose-Dienstes.</li>\n<li><code>DiagnosticMapping</code> (spezialisiert <code>DiagnosticCommonElement</code>): Abstrakte Basisklasse für Diagnose-Zuordnungen.</li>\n<li><code>DiagnosticSwMapping</code> (spezialisiert <code>DiagnosticMapping</code>): Spezifische Basis für Software-bezogene Diagnose-Mappings.</li>\n<li><code>DiagnosticUploadDownloadPortMapping</code> (spezialisiert <code>DiagnosticSwMapping</code>): Zentrales Mapping-Element für Upload-/Download-Ports.</li>\n<li>Assoziation <code>+serviceInstance</code> (Kardinalität <code>0..1</code>) zu <code>DiagnosticServiceInstance</code>.</li>\n<li>Assoziation <code>+process</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«atpSplitable»</code>) zu <code>ProcessDesign</code>.</li>\n<li>Assoziation <code>+swcServiceDependencyInExecutable</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«instanceRef»</code>) zu <code>SwcServiceDependency</code>.</li>\n<li><code>ProcessDesign</code> (Spezialisierung von <code>ARElement</code>): Modelliert den Entwurf eines Prozesses; verknüpft über die Assoziation <code>+design</code> (Kardinalität <code>0..1</code>) mit <code>Process</code>.</li>\n<li><code>Process</code> (spezialisiert <code>AbstractExecutionContext</code>): Ausführungskontext mit den Attributen:</li>\n<li><code>logTraceDefaultLogLevel: LogTraceDefaultLogLevelEnum [0..1]</code></li>\n<li><code>logTraceFilePath: UriString [0..1]</code></li>\n<li><code>logTraceLogMode: LogTraceLogModeEnum [0..*]</code></li>\n<li><code>logTraceProcessDesc: String [0..1]</code></li>\n<li><code>logTraceProcessId: String [0..1]</code></li>\n<li><code>numberOfRestartAttempts: PositiveInteger [0..1]</code></li>\n<li><code>preMapping: Boolean [0..1]</code></li>\n<li><code>SwcServiceDependency</code> (spezialisiert <code>ServiceDependency</code>, <code>Identifiable</code>, <code>AtpStructureElement</code>): Beschreibt Service-Abhängigkeiten einer Software-Komponente; besitzt eine Komposition <code>+serviceNeeds</code> (Kardinalität <code>1</code>) zu <code>ServiceNeeds</code>.</li>\n<li><code>ServiceNeeds</code> (spezialisiert <code>Identifiable</code>): Abstrakter Dienstbedarf.</li>\n<li><code>DiagnosticCapabilityElement</code> (spezialisiert <code>ServiceNeeds</code>): Spezifiziert Diagnosefähigkeiten mit Attributen:</li>\n<li><code>audience: DiagnosticAudienceEnum [0..*]</code></li>\n<li><code>diagRequirement: DiagRequirementIdString [0..1]</code></li>\n<li><code>securityAccessLevel: PositiveInteger [0..1]</code></li>\n<li><code>DiagnosticUploadDownloadNeeds</code> (spezialisiert <code>DiagnosticCapabilityElement</code>): Konkreter Service-Bedarf für Diagnose-Upload- und Download-Vorgänge.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Strukturdiagramm bildet dieses Diagramm keine direkten Laufzeit- oder Sequenzabläufe ab. Es spezifiziert die deklarativen Zusammenhänge der Manifest-Modellierung zur Entwurfs- und Konfigurationszeit: Eine Software-Komponente deklariert über <code>SwcServiceDependency</code> ihren Bedarf an Diagnose-Upload/-Download-Funktionen (<code>DiagnosticUploadDownloadNeeds</code>). <code>DiagnosticUploadDownloadPortMapping</code> verknüpft diese Service-Abhängigkeit instanzreferenzierend (<code>«instanceRef»</code>) mit der konkreten <code>DiagnosticServiceInstance</code> sowie mit dem zugehörigen Ausführungsprozess (<code>ProcessDesign</code> bzw. <code>Process</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modell definiert verbindliche Vorgaben für die Manifest-Konfiguration der AUTOSAR Adaptive Platform. Attribute wie <code>numberOfRestartAttempts</code>, <code>preMapping</code> und Logging-Konfigurationen (<code>logTrace...</code>) steuern die Initialisierung, Fehlerbehandlung und Ablaufüberwachung des Prozesses durch das adaptive Ausführungsmanagement (Execution Management). Die Instanzreferenz <code>swcServiceDependencyInExecutable</code> stellt die formale Brücke zwischen komponentenseitigem Service-Bedarf und der Bereitstellung auf Plattformebene dar; die Splitbarkeit (<code>«atpSplitable»</code>) der Assoziation zum Prozess erlaubt die Verteilung der Manifest-Artefakte über getrennte Modelldateien (z. B. Trennung von Applikations- und Maschinenkonfiguration).</p>"}], "trans": [{"from": "FIG-38e714e67caca8d6", "to": "FIG-e24062be900c61bc", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>In Klasse <code>Process</code> wurde die Kardinalität des Attributs <code>logTraceLogMode</code> von <code>[0..1]</code> auf <code>[0..*]</code> geändert.</li>\n<li>In Klasse <code>Process</code> wurde das Attribut <code>numberOfRestartAttempts: PositiveInteger [0..1]</code> hinzugefügt.</li>\n</ul>"}]};
